<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigRateLimitAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigRateLimitAccessor trait.
 *
 * Covers null default, string/VO assignment via withRateLimit,
 * getRateLimit/rateLimit accessors, and isRateLimitChanged with/without original.
 */
class SmtpOutboundConfigRateLimitAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRateLimit creates a new instance with the RateLimit set
     * from a string value, and getRateLimit returns the primitive string.
     */
    public function testWithRateLimitFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRateLimitAccessorUnitTest();

        // Act
        $result = $holder->withRateLimit(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getRateLimit());
    }
    /**
     * Asserts that withrateLimit has access to the value object
     * from a string value, and getRateLimit returns the primitive string.
     */
    public function testWithRateLimitFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRateLimitAccessorUnitTest();

        // Act
        $result = $holder->withRateLimit(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->rateLimit()->value());
    }
    public function testChangedRateLimit(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRateLimitAccessorUnitTest()->withRateLimit(1);
        $original = $holder->withRateLimit(1);
        $same = $holder->withRateLimit(1);
        $modified = $holder->withRateLimit(2);

        // Act
        $withSame = $original->isRateLimitChanged($same);
        $withDiferent = $original->isRateLimitChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigRateLimitAccessorUnitTest
{
    use SmtpOutboundConfigRateLimitAccessor;
}
